import json
from pathlib import Path
from html import escape
from datetime import datetime
base=Path(__file__).parent
source=Path('examples/knowledge-lab/content.json')
d=json.loads(source.read_text()); counts=d['counts']; total=sum(x['value'] for x in counts)
assert total==24
stamp=datetime.now().astimezone().strftime('%Y-%m-%d %H:%M:%S %Z')
rows=''.join(f'<li><div class="label"><span>{escape(x["label"])}</span><strong>{x["value"]}</strong></div><div class="track"><span style="width:{x["value"]/max(y["value"] for y in counts)*100}%"></span></div></li>' for x in counts)
parts=''.join(f'<div style="flex:{x["value"]}">{x["value"]}</div>' for x in counts)
table=''.join(f'<tr><th scope="row">{escape(x["label"])}</th><td>{x["value"]}</td></tr>' for x in counts)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A closer look at repair | Infographic study</title><style>
h1,h2{text-wrap:balance}p{ text-wrap:pretty}*{box-sizing:border-box}body{margin:0;background:#e8e4dc;color:#182e52;font-family:Arial,sans-serif;line-height:1.5}main{max-width:1120px;margin:auto;padding:48px 24px}h1,h2,p{margin:0}h1{font-size:clamp(32px,6vw,66px);line-height:1.04;letter-spacing:-.04em;max-width:760px}header>p{max-width:650px;margin-top:22px}.kicker{text-transform:uppercase;font-size:12px;letter-spacing:.14em;font-weight:bold}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:40px 0}.board{padding:36px;background:#f5f0e6;border-top:5px solid #182e52;display:flex;flex-direction:column;gap:24px;min-width:0}.board h2{font-size:34px;line-height:1.1;letter-spacing:-.03em}.board.dark{background:#182e52;color:#f5f0e6;border-color:#a73832}.number{font-size:100px;line-height:1;font-weight:bold;letter-spacing:-.07em}.number span{margin-left:8px;font-size:20px;letter-spacing:0;font-weight:normal}.bars{list-style:none;padding:0;margin:0}.bars li{margin-bottom:20px}.label{display:flex;justify-content:space-between;margin-bottom:6px}.track{height:18px;background:#ded8cd}.track span{height:100%;background:#213f82;display:block}.whole{display:flex;height:64px;gap:0}.whole div{display:grid;place-items:center;background:#f5f0e6;color:#182e52;border:0;font-weight:bold}.whole div:not(:last-child){box-shadow:inset -1px 0 #182e52}.whole div:nth-child(2){background:#c5cfe1}.whole div:nth-child(3){background:#aabbd7}.note{font-size:13px;border-top:1px solid currentColor;padding-top:16px;margin-top:auto}.rationale{font-size:15px;max-width:800px;margin:24px 0}details{border-top:1px solid #182e52;padding:20px 0}details[open]>p{margin-top:18px}summary{cursor:pointer;font-weight:bold}summary:focus-visible{outline:3px solid #a73832;outline-offset:5px}table{border-collapse:collapse;width:100%;max-width:480px;margin-top:20px}th,td{text-align:left;padding:10px;border-bottom:1px solid #999}footer{font-size:12px;margin-top:24px} @media(max-width:700px){main{padding:28px 18px}.grid{grid-template-columns:1fr}.board{padding:26px}.number{font-size:80px}}@media print{body{background:white}main{padding:0}.grid{gap:16px;margin:20px 0}.board{break-inside:avoid;padding:24px}.board.dark{print-color-adjust:exact;-webkit-print-color-adjust:exact}details{break-before:page;display:block}details summary{display:none}h1{font-size:40px}footer{font-size:10px}}
</style><main><header><p class="kicker">Information design / two directions</p><h1>A closer look at repair.</h1><p>One fictional dataset. Two ways to explain it. These examples compare repair categories; they do not measure repair difficulty, cost, time, or real demand.</p></header><div class="grid"><section class="board" aria-labelledby="compare"><p class="kicker">01 / Compare the categories</p><h2 id="compare">Buttons lead this sample.</h2><p>Of 24 fictional items, 12 involve buttons, 8 involve seams, and 4 involve patches.</p><ul class="bars">ROWS</ul><p class="note">Bar lengths share a zero baseline. The longest bar represents 12 items. Synthetic counts, not observed results.</p></section><section class="board dark" aria-labelledby="whole"><p class="kicker">02 / Start with the takeaway</p><h2 id="whole">Half are button repairs.</h2><p class="number">12<span> of 24 items</span></p><div class="whole" role="img" aria-label="24 total: buttons 12, seams 8, patches 4">PARTS</div><p>Buttons 12 · Seams 8 · Patches 4</p><p>The other half is split between seams and patches. This bar is scaled to all 24 items. The comparison chart is scaled to its largest category, 12. Segment order follows the labels above.</p><p class="note">This is a fictional category mix. It is not a claim about typical repairs or service outcomes.</p></section></div><p class="rationale"><strong>Why these directions:</strong> the first helps readers compare categories quickly. The second emphasizes the button share while preserving the complete breakdown. Neither introduces a conclusion beyond the supplied values.</p><details><summary>Read the data and accessible explanation</summary><p>There are 24 synthetic items. Buttons account for 12, exactly half. Seams account for 8 and patches for 4. Buttons are the largest category; patches are the smallest. These numbers provide no evidence about actual customer behavior.</p><table><caption>Synthetic repair categories</caption><thead><tr><th scope="col">Category</th><th scope="col">Items</th></tr></thead><tbody>TABLE<tr><th scope="row">Total</th><td>24</td></tr></tbody></table></details><footer>Internal fictional study. Source: repair-information-fiction-01, knowledge laboratory content.json. Direction approval and audience comprehension remain untested.<br>Version-Timestamp: STAMP</footer></main></html>'''
(base/'index.html').write_text(html.replace('ROWS',rows).replace('PARTS',parts).replace('TABLE',table).replace('STAMP',stamp))
(base/'data.json').write_text(json.dumps({'Version-Timestamp':stamp,'source':str(source),'status':'synthetic','counts':counts,'total':total},indent=2)+'\n')
print('Built two directions from one synthetic dataset')
